func TestClosureObservations(t *testing.T) {
	cases := []struct {
		name   string
		values []int
	}{
		{"nil", nil},
		{"empty", []int{}},
		{"queued-zero", []int{0}},
		{"mixed", []int{3, 0, -2}},
		{"four", []int{-4, -4, 0, 8}},
