package main

import (
	"fmt"

	"finite.local/channel-permissions/channel"
)

func main() {
	report := channel.Observe([]int{3, 0, -2})
	for index, reading := range report.Readings {
		fmt.Printf("reading %d: value=%d ok=%t ready=%t\n", index, reading.Value, reading.OK, reading.Ready)
	}
	fmt.Printf("send-after-close panic: %t\n", report.SendPanicked)
	fmt.Printf("second-close panic: %t\n", report.ClosePanicked)
}

channel/observe.go.text:
package channel

func publish(dst chan<- int, values []int) {
	for _, value := range values {
		dst <- value
	}
	close(dst)
}

func take(src <-chan int) Reading {
	select {
	case value, ok := <-src:
		return Reading{Value: value, OK: ok, Ready: true}
	default:
		return Reading{}
	}
}

func Observe(values []int) Report {
	owner := make(chan int, len(values))
	publish(owner, values)
	report := Report{Readings: make([]Reading, 0, len(values)+2)}
	for count := 0; count < len(values)+2; count++ {
		report.Readings = append(report.Readings, take(owner))
	}
	report.SendPanicked = observePanic(func() {
		select {
		case owner <- 91:
		default:
		}
	})
	report.ClosePanicked = observePanic(func() { close(owner) })
	return report
}

